parameters.jsCode:
const body = $input.first().json.body || {};
const job_id = body.job_id;
const blogger = body.blogger;
const platform = body.platform;
const channel_id = body.channel_id;
const content = body.content || '';
const media_url = String(body.media_url || body.image_url || '').trim();
const media_url_b = String(body.media_url_b || '').trim();
const chat_id = String(body.chat_id || '492912584');
return [{
  json: {
    job_id,
    blogger,
    platform,
    channel_id,
    content,
    media_url,
    media_url_b,
    chat_id,
    caption_single: `🖼 ${job_id} | ${blogger} | ${platform}`,
    text_no_image: `⚠️ Картинка не сгенерирована\n\n${content}`
  }
}];

const data = $input.first().json.body;

if (data.callback_query) {
  const cb = data.callback_query;
  const cbData = String(cb.data || '');
  let action;
  let jobId;
  if (cbData.startsWith('approve_a_')) {
    action = 'approve_a';
    jobId = cbData.slice('approve_a_'.length);
  } else if (cbData.startsWith('approve_b_')) {
    action = 'approve_b';
    jobId = cbData.slice('approve_b_'.length);
  } else if (cbData.startsWith('approve_')) {
    action = 'approve';
    jobId = cbData.slice('approve_'.length);
  } else if (cbData.startsWith('reject_')) {
    action = 'reject';
    jobId = cbData.slice('reject_'.length);
  } else if (cbData.startsWith('revise_')) {
    action = 'revise';
    jobId = cbData.slice('revise_'.length);
  } else {
    const underscoreIdx = cbData.indexOf('_');
    action = underscoreIdx === -1 ? cbData : cbData.substring(0, underscoreIdx);
    jobId = underscoreIdx === -1 ? '' : cbData.substring(underscoreIdx + 1);
  }
  return [{
    json: {
      event_type: 'callback',
      action,
      job_id: jobId,
      message_id: cb.message.message_id,
      chat_id: cb.from.id,
      callback_query_id: cb.id
    }
  }];
}

if (data.message) {
  return [{
    json: {
      event_type: 'message',
      text: data.message.text || '',
      chat_id: data.message.chat.id,
      from_id: data.message.from.id,
      message_id: data.message.message_id
    }
  }];
}

return [{ json: { event_type: 'unknown' } }];

const fs = require('fs');

const blogger = $json.blogger;
const jobId = $json.job_id;
if (!blogger || !jobId) return [{ json: $json }];

const reportPath = `/home/node/shared/bloggers/${blogger}/jobs/${jobId}/launch_report.md`;
const marker = '## Telegram API result';

// n8n HTTP Request often exposes Telegram response either at root ($json) or in $json.body
const telegram = $json.result ? $json : ($json.body?.result ? { result: $json.body.result } : $json);
const result = telegram.result || {};
const messageId = result.message_id;

let report = '';
try {
  report = fs.existsSync(reportPath) ? fs.readFileSync(reportPath, 'utf8') : '';
} catch (e) {
  // ignore read errors
}

const block = `\n\n${marker}\n- message_id: ${messageId ?? ''}\n`;
if (report) {
  if (!report.includes(marker)) {
    fs.writeFileSync(reportPath, report.trimEnd() + block);
  } else {
    // best-effort: replace message_id line if present
    const replaced = report.replace(/- message_id:\s*.*\n/, `- message_id: ${messageId ?? ''}\n`);
    fs.writeFileSync(reportPath, replaced);
  }
} else {
  // minimal fallback
  fs.writeFileSync(reportPath, block);
}

return [{ json: $json }];

const jobId = $json.job_id;
const action = $json.action;
const fs = require('fs');
const filePath = `/home/node/shared/approvals/${jobId}.json`;

let approvalData;
try {
  approvalData = JSON.parse(fs.readFileSync(filePath, 'utf8'));
} catch(e) {
  throw new Error(`Файл не найден: ${filePath}`);
}

const mu = String(approvalData.media_url || approvalData.image_url || '').trim();
const mub = String(approvalData.media_url_b || '').trim();

let selected_media_url = '';
if (action === 'approve_a') selected_media_url = mu;
else if (action === 'approve_b') selected_media_url = mub;
else if (action === 'approve') selected_media_url = mu || mub;

if (selected_media_url && ['approve', 'approve_a', 'approve_b'].includes(action)) {
  const blogger = approvalData.blogger;
  const jobDir = `/home/node/shared/bloggers/${blogger}/jobs/${jobId}`;
  const lockPath = `${jobDir}/published.lock`;
  try {
    if (!fs.existsSync(jobDir)) fs.mkdirSync(jobDir, { recursive: true });
    fs.writeFileSync(lockPath, JSON.stringify({ selected_media_url: selected_media_url }, null, 2));
  } catch (e) {}
}

return [{
  json: {
    ...approvalData,
    job_id: jobId,
    image_url: selected_media_url || approvalData.image_url || '',
    message_id: $json.message_id,
    chat_id_user: $json.chat_id,
    callback_query_id: $json.callback_query_id,
    action
  }
}];

const text = $json.text;

// Парсим формат: "правки JOB_ID: текст правок"
const match = text.match(/^правки\s+(\S+):\s*(.+)$/s);

if (!match) {
  return [{
    json: {
      valid: false,
      raw_text: text
    }
  }];
}

return [{
  json: {
    valid: true,
    job_id: match[1],
    revision_text: match[2],
    chat_id: $json.chat_id
  }
}];

const jobId = $json.job_id;
const revisionText = $json.revision_text;
const fs = require('fs');

// Читаем данные задачи
const filePath = `/home/node/shared/approvals/${jobId}.json`;
let approvalData;
try {
  approvalData = JSON.parse(fs.readFileSync(filePath, 'utf8'));
} catch(e) {
  throw new Error(`Файл не найден: ${filePath}`);
}

return [{
  json: {
    ...approvalData,
    job_id: jobId,
    revision_text: revisionText,
    hook_message: `Правки от редактора для job ${jobId}: ${revisionText}. Верни Quill на доработку.`
  }
}];

const fs = require('fs');

const blogger = $json.blogger;
const jobId = $json.job_id;
if (!blogger || !jobId) return [{ json: $json }];

const reportPath = `/home/node/shared/bloggers/${blogger}/jobs/${jobId}/launch_report.md`;
const marker = '## Telegram API result';

const telegram = $json.result ? $json : ($json.body?.result ? { result: $json.body.result } : $json);
const result = telegram.result || {};
const messageId = result.message_id;

let report = '';
try {
  report = fs.existsSync(reportPath) ? fs.readFileSync(reportPath, 'utf8') : '';
} catch (e) {}

const block = `\n\n${marker}\n- message_id: ${messageId ?? ''}\n`;
if (report) {
  if (!report.includes(marker)) {
    fs.writeFileSync(reportPath, report.trimEnd() + block);
  } else {
    const replaced = report.replace(/- message_id:\s*.*\n/, `- message_id: ${messageId ?? ''}\n`);
    fs.writeFileSync(reportPath, replaced);
  }
} else {
  fs.writeFileSync(reportPath, block);
}

return [{ json: $json }];

const now = new Date();
now.setDate(now.getDate() + 1);
const weekStart = now.toISOString().split('T')[0];

const channels = [
  { blogger: 'tomas-food', platform: 'tg', niche: 'food тренды', posts_per_day: 2 },
  { blogger: 'tomas-vibe', platform: 'tg', niche: 'AI/tech тренды', posts_per_day: 2 },
  { blogger: 'misha', platform: 'yt', niche: 'барная индустрия, кофе, HoReCa, Большая Азия, бариста', posts_per_day: 3 },
  { blogger: 'nasik', platform: 'tt', niche: 'барная индустрия, кофе, HoReCa, Большая Азия, бариста', posts_per_day: 3 },
  { blogger: 'yulya', platform: 'ig', niche: 'барная индустрия, кофе, HoReCa, Большая Азия, бариста', posts_per_day: 3 },
];

return channels.map(ch => ({ json: { ...ch, week_start: weekStart } }));

