parameters.jsCode:
const results = [];

for (const item of $input.all()) {
  const raw = item.json.body ?? item.json;
  const text = raw.content?.[0]?.text || raw.choices?.[0]?.message?.content || '';

  const match = text.match(/\[[\s\S]*\]/);
  if (!match) continue;

  try {
    const topics = JSON.parse(match[0]);
    for (const t of topics) {
      results.push({ json: t });
    }
  } catch(e) {
    continue;
  }
}

return results;

const today = new Date().toISOString().split('T')[0];

const rowsToDelete = $input.all().filter(item => {
  return item.json.date < today;
});

return rowsToDelete.map(item => ({ json: { row_number: item.json.row_number } }));
